const input = $input.first().json;

// 1. Get action from the root
const action = input.action || 'listAll';

// 2. Safely parse params (since it's a string in your input)
let params = {};
try {
  params = (typeof input.params === 'string') ? JSON.parse(input.params) : (input.params || {});
} catch (e) {
  params = {}; // Fallback if JSON is malformed
}

// 3. Calculate next_run_date (Today + interval_days)
let nextRunDate = null;
const interval = params.interval_days ? Number(params.interval_days) : null;

if (interval) {
  const date = new Date();
  date.setDate(date.getDate() + interval);
  nextRunDate = date.toISOString().split('T')[0]; // Returns "YYYY-MM-DD"
}

const session_id = input.session_id;
const usecase_id = input.usecase_id;

return [{
  json: {
    action: action,
    session_id: session_id,
    usecase_id: usecase_id,
    next_run_date: nextRunDate, // <-- FIXED: Added this so subsequent nodes can access it

    // Use Number() or parseInt() to ensure these are integers
    schedule_id: params.schedule_id ? Number(params.schedule_id) : null,
    user_id: params.user_id ? Number(params.user_id) : null,
    interval_days: params.interval_days ? Number(params.interval_days) : null,
    trigger_percentage: params.trigger_percentage ? (Number(params.trigger_percentage) <= 1 ? Number(params.trigger_percentage) * 100 : Number(params.trigger_percentage)) : null,
    measure_type: params.measure_type || 'average',

    // <-- FIXED: Clean boolean logic
    isValid: !!((action === 'list') || (action === 'listAll') ||
               (action === 'add' && params.user_id && params.interval_days) ||
               (action === 'change' && params.schedule_id) ||
               (action === 'deactivate' && params.schedule_id) ||
               (action === 'activate' && params.schedule_id))
  }
}];

